#include <vector>
#include <unordered_map>
#include <unordered_set>

class Solution {
public:
    int countFrequencyBalancedSubarrays(std::vector<int>& nums, int k) {
        int n = nums.size();
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            std::unordered_map<int, int> counts;
            for (int j = i; j < n; ++j) {
                counts[nums[j]]++;
                if ((int)counts.size() == k) {
                    int expected = counts.begin()->second;
                    bool balanced = true;
                    for (auto const& [val, freq] : counts) {
                        if (freq != expected) {
                            balanced = false;
                            break;
                        }
                    }
                    if (balanced) ans++;
                } else if ((int)counts.size() > k) {
                    break;
                }
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int countFrequencyBalancedSubarrays(int[] nums, int k) {
        int n = nums.length;
        int ans = 0;
        for (int i = 0; i < n; i++) {
            Map<Integer, Integer> counts = new HashMap<>();
            for (int j = i; j < n; j++) {
                counts.put(nums[j], counts.getOrDefault(nums[j], 0) + 1);
                if (counts.size() == k) {
                    int first = counts.values().iterator().next();
                    boolean balanced = true;
                    for (int freq : counts.values()) {
                        if (freq != first) {
                            balanced = false;
                            break;
                        }
                    }
                    if (balanced) ans++;
                } else if (counts.size() > k) {
                    break;
                }
            }
        }
        return ans;
    }
}

